import re


_NAME_SEPARATOR = re.compile(r"[\s-]+")


def asset_key(name, revision):
    """Return the storage key for an asset name and positive revision."""
    if isinstance(revision, bool) or not isinstance(revision, int) or revision <= 0:
        raise ValueError("revision must be a positive integer")

    if not isinstance(name, str):
        raise TypeError("name must be a string")

    normalized_name = _NAME_SEPARATOR.sub("_", name.strip().lower())
    if not normalized_name:
        raise ValueError("name must not be empty")

    return f"assets/v{revision}/{normalized_name}.bin"

