import unittest

from assets import asset_key


class AssetKeyTests(unittest.TestCase):
    def test_normalizes_name_and_builds_storage_key(self):
        self.assertEqual(
            asset_key("  Hero  Image--XL ", 2),
            "assets/v2/hero_image_xl.bin",
        )

    def test_handles_unicode_whitespace(self):
        self.assertEqual(asset_key("A\u00a0B - C", 1), "assets/v1/a_b_c.bin")

    def test_preserves_other_name_characters(self):
        self.assertEqual(
            asset_key("name/with.other_chars", 7),
            "assets/v7/name/with.other_chars.bin",
        )

    def test_rejects_invalid_revisions(self):
        for revision in (0, -1, 1.5, "1", None, True, False):
            with self.subTest(revision=revision):
                with self.assertRaises(ValueError):
                    asset_key("valid", revision)

    def test_rejects_invalid_names(self):
        for name in ("", "   "):
            with self.subTest(name=name):
                with self.assertRaises(ValueError):
                    asset_key(name, 1)

        for name in (None, 123):
            with self.subTest(name=name):
                with self.assertRaises(TypeError):
                    asset_key(name, 1)


if __name__ == "__main__":
    unittest.main()
